package net.minecraft.world.item;import net.minecraft.network.chat.Component;public class ItemStack{public static final ItemStack EMPTY=new ItemStack(new Item("minecraft:air"),0);public Item item;public int count,ammo=0,damage=0;public String component="",gunId="tacz:pistol",ammoId="tacz:9mm";public boolean barrel;public ItemStack(net.minecraft.world.level.ItemLike item,int n){this.item=(Item)item;count=n;}public Item getItem(){return item;}public boolean isEmpty(){return count<=0;}public int getCount(){return count;}public void setCount(int n){count=n;}public int getMaxStackSize(){return 64;}public void shrink(int n){count-=n;}public ItemStack copy(){ItemStack s=new ItemStack(item,count);s.ammo=ammo;s.component=component;s.gunId=gunId;s.ammoId=ammoId;s.barrel=barrel;s.damage=damage;return s;}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.item.id.equals(b.item.id)&&a.component.equals(b.component)&&a.gunId.equals(b.gunId);}public Object set(Object k,Object v){component=v.toString();return v;}public Component getHoverName(){return Component.literal(item.id);}public void hurtAndBreak(int n,Object p,Object slot){damage+=n;}}
